// Log helpers: the kernel-log replacement for pr_debug/pr_notice/DRM_DEBUG_KMS.
macro_rules! edid_dbg {
    ($($arg:tt)*) => {
        drm_log_at(DrmLogLevel::Debug, "drm_edid", file!(), line!(), &format!($($arg)*))
    };
}
macro_rules! edid_notice {
    ($($arg:tt)*) => {
        drm_log_at(DrmLogLevel::Info, "drm_edid", file!(), line!(), &format!($($arg)*))
    };
}
macro_rules! edid_warn {
    ($($arg:tt)*) => {
        drm_log_at(DrmLogLevel::Warn, "drm_edid", file!(), line!(), &format!($($arg)*))
    };
}

#[inline]
const fn bit(n: u32) -> u32 {
    1 << n
}

// upstream: include/drm/drm_edid.h drm_edid_encode_panel_id()
const fn encode_panel_id(c0: char, c1: char, c2: char, product_id: u32) -> u32 {
    ((((c0 as u32) - ('@' as u32)) & 0x1f) << 26)
        | ((((c1 as u32) - ('@' as u32)) & 0x1f) << 21)
        | ((((c2 as u32) - ('@' as u32)) & 0x1f) << 16)
        | (product_id & 0xffff)
}

